func TestDecodeRoundTrips(t *testing.T) {
	input := `{
	"name": "one"
}`
	rec, err := Decode([]byte(input))
	if err != nil {
		t.Fatalf("Decode: %v", err)
	}
	out, err := Encode(rec)
	if err != nil {
		t.Fatalf("Encode: %v", err)
	}
	back, err := Decode(out)
	if err != nil {
		t.Fatalf("Decode(Encode): %v", err)
	}
	if !reflect.DeepEqual(back, rec) {
		t.Fatalf("round trip = %+v, want %+v", back, rec)
	}
}

